function buildSecurityArticle(spec: AiArticleSpec): BlogPost {
  const base=buildProgrammingArticle(spec);
  return {...base,category:"cybersecurity-privacy",relatedTools:[{name:"Password Generator",href:"/password-generator"},{name:"QR & Security Tools",href:"/category/qr-security"}],faqs:[
    {question:`What is ${spec.focus}?`,answer:`${spec.definition} Security guidance reduces risk, but no single control can guarantee complete protection.`},
    {question:"What is the most important first step?",answer:"Protect your primary email, update devices, use unique passwords through a reputable manager and enable the strongest multi-factor authentication each important account supports."},
    {question:"Can one security tool keep me completely safe?",answer:"No. Effective security uses layers such as updates, authentication, limited permissions, careful verification, monitoring and recovery plans."},
    {question:"What should I do if I suspect compromise?",answer:"Use a trusted device to change affected credentials, revoke sessions, contact the provider through an official channel, preserve relevant evidence and monitor connected accounts. Report financial fraud promptly."},
    {question:"How often should security settings be reviewed?",answer:"Review important accounts periodically and whenever you change devices, receive a breach notice, notice suspicious activity or a provider introduces stronger authentication options."},
    {question:"Where should I get current security advice?",answer:"Prefer official guidance from the affected provider and established authorities such as CISA, NIST, OWASP or your national cybersecurity agency. Avoid instructions that require disabling protections."},
  ]};
}

const securityPosts=securityArticleSpecs.map(buildSecurityArticle);
export const blogPosts: BlogPost[] = [...aiPosts, ...webPosts, ...programmingPosts, ...developerToolPosts, ...securityPosts, ...editorialPosts];

export function getBlogCategory(slug: string) {
  return blogCategories.find((category) => category.slug === slug);
}

export function getBlogPost(slug: string) {
  return blogPosts.find((post) => post.slug === slug);
}

export function getPostsByCategory(category: BlogCategorySlug) {
  return blogPosts.filter((post) => post.category === category);
}

export function formatBlogDate(date: string) {
  return new Intl.DateTimeFormat("en-IN", { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" }).format(new Date(`${date}T00:00:00Z`));
}
